test('local drafts recover exact request after reload, isolate tabs, and support deletion',async({page,context})=>{
 await ready(page);await expect(page.locator('#draft-status')).toContainText('No local draft yet');await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('789');await done(page);await page.locator('#advanced summary').click();const request=page.locator('#request');const value=await request.inputValue();const text=value.replace(/}\s*$/,', "unknown_big": 900719925474099312345}');await request.fill(text);await page.locator('#advanced summary').click();await expect(page.locator('#draft-status')).toContainText('saved locally');
 const other=await context.newPage();await ready(other);await expect(other.locator('#draft-status')).toContainText('local draft');await edit(other,'output');await expect(other.getByLabel('Output index 0 capacity (CKB)')).toHaveValue('1000');await other.getByLabel('Output index 0 capacity (CKB)').fill('888');await done(other);await expect.poll(()=>other.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('ckb-vm-js:draft:')).length)).toBe(2);
 page.once('dialog',d=>d.accept());await page.reload();await expect(page.locator('#status')).toHaveText('Ready');await expect(page.locator('#draft-status')).toContainText('local draft');await page.locator('#local-drafts summary').click();const key=await page.evaluate(expected=>Object.keys(localStorage).find(k=>k.startsWith('ckb-vm-js:draft:')&&JSON.parse(localStorage.getItem(k)).text===expected),text);await page.locator(`[data-draft-key="${key}"]`).getByRole('button',{name:/Restore/}).click();expect(await request.inputValue()).toBe(text);await expect(page.locator('#status')).toHaveText('Edited');await expect(page.locator('#local-drafts summary')).toBeFocused();await page.locator('#local-drafts summary').click();const before=await page.locator('.draft-row').count();page.once('dialog',d=>d.accept());await page.locator('.draft-row').first().getByRole('button',{name:/Delete/}).click();await expect(page.locator('.draft-row')).toHaveCount(before-1);expect(await request.inputValue()).toBe(text);await other.close();
});

test('local draft survives import and sample replacement cancellation; export leaves it available',async({page})=>{
 await ready(page);const input=page.locator('#request');const fixture=JSON.parse(await input.inputValue());fixture.custom={large:'900719925474099312345',retained:true};await page.locator('.example-menu summary').click();await page.locator('#upload').setInputFiles({name:'custom.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await expect.poll(async()=>JSON.parse(await input.inputValue()).custom?.retained).toBe(true);const imported=await input.inputValue();await expect(page.locator('#draft-status')).toContainText('saved locally');await page.locator('#sample').selectOption('script-failure');page.once('dialog',d=>d.dismiss());await page.getByRole('button',{name:'Load sample'}).click();expect(await input.inputValue()).toBe(imported);
 const downloadEvent=page.waitForEvent('download');await page.getByRole('button',{name:'Export JSON'}).click();const download=await downloadEvent;const stream=await download.createReadStream();let output='';for await(const chunk of stream)output+=chunk.toString();expect(JSON.parse(output).custom).toEqual(fixture.custom);await page.reload();await expect(page.locator('#draft-status')).toContainText('local draft');await page.locator('#local-drafts summary').click();await page.getByRole('button',{name:/Restore Imported JSON/}).click();expect(await input.inputValue()).toBe(imported);
});

test('deleting another tab’s local draft updates its status without recreating it',async({page,context})=>{
 await ready(page);await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('789');await done(page);const aBefore=await page.locator('#request').inputValue();const aKey=await page.evaluate(expected=>Object.keys(localStorage).find(k=>k.startsWith('ckb-vm-js:draft:')&&JSON.parse(localStorage.getItem(k)).text===expected),aBefore);
 const other=await context.newPage();await ready(other);await edit(other,'output');await other.getByLabel('Output index 0 capacity (CKB)').fill('888');await done(other);
 const before=await other.locator('#request').inputValue();const key=await other.evaluate(expected=>Object.keys(localStorage).find(k=>k.startsWith('ckb-vm-js:draft:')&&JSON.parse(localStorage.getItem(k)).text===expected),before);expect(key).toBeTruthy();
 await page.locator('#local-drafts summary').click();page.once('dialog',d=>d.accept());await page.locator(`[data-draft-key="${key}"]`).getByRole('button',{name:/Delete/}).click();
 await expect(other.locator('#draft-status')).toContainText('no current local draft');await expect(other.getByRole('button',{name:'Save local draft'})).toBeVisible();expect(await other.locator('#request').inputValue()).toBe(before);expect(await other.evaluate(k=>localStorage.getItem(k),key)).toBeNull();expect(JSON.parse(await page.evaluate(k=>localStorage.getItem(k),aKey)).text).toBe(aBefore);
 await other.locator('#local-drafts summary').click();await other.getByRole('button',{name:'Refresh draft list'}).click();await expect(other.locator('#draft-status')).toContainText('no current local draft');expect(await other.evaluate(k=>localStorage.getItem(k),key)).toBeNull();await edit(other,'output');await other.getByRole('button',{name:'Cancel changes'}).click();expect(await other.evaluate(k=>localStorage.getItem(k),key)).toBeNull();expect(await other.locator('#request').inputValue()).toBe(before);
 await other.evaluate(()=>{window.originalDraftSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(){throw new DOMException('Blocked','SecurityError');};});await other.getByRole('button',{name:'Save local draft'}).click();await expect(other.locator('#draft-status')).toContainText('could not be saved');expect(await other.locator('#request').inputValue()).toBe(before);expect(await other.evaluate(k=>localStorage.getItem(k),key)).toBeNull();await other.evaluate(()=>{Storage.prototype.setItem=window.originalDraftSetItem;});await other.getByRole('button',{name:'Save local draft'}).click();await expect(other.locator('#local-drafts summary')).toBeFocused();await expect(other.locator('#draft-status')).toContainText('saved locally');expect(JSON.parse(await other.evaluate(k=>localStorage.getItem(k),key)).text).toBe(before);
 other.once('dialog',d=>d.accept());await other.reload();await other.locator('#local-drafts summary').click();await other.locator(`[data-draft-key="${key}"]`).getByRole('button',{name:/Restore/}).click();expect(await other.locator('#request').inputValue()).toBe(before);await other.close();
});

