 for(let i=0;i<2;i++){await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('777');expect(await page.evaluate(k=>localStorage.getItem(k),key)).toBeNull();await page.getByRole('button',{name:'Cancel changes'}).click();expect(await page.locator('#request').inputValue()).toBe(before);await expect(page.locator('#draft-status')).toContainText('no current local draft');expect(await page.evaluate(k=>localStorage.getItem(k),key)).toBeNull();}
