 await edit(page,'output');await page.evaluate(k=>localStorage.removeItem(k),key);await page.getByLabel('Output index 0 capacity (CKB)').fill('777');expect(await page.evaluate(k=>localStorage.getItem(k),key)).toBeNull();await page.getByRole('button',{name:'Cancel changes'}).click();expect(await page.locator('#request').inputValue()).toBe(before);await expect(page.locator('#draft-status')).toContainText('no current local draft');await page.getByRole('button',{name:'Save local draft'}).click();
 other.once('dialog',d=>d.accept());await other.getByRole('button',{name:'Refresh draft list'}).click();await other.locator(`[data-draft-key="${key}"]`).getByRole('button',{name:/Delete/}).click();await expect(page.locator('#draft-status')).toContainText('no current local draft');await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('777');expect(await page.evaluate(k=>localStorage.getItem(k),key)).toBeNull();await done(page);const applied=await page.locator('#request').inputValue();expect(JSON.parse(await page.evaluate(k=>localStorage.getItem(k),key)).text).toBe(applied);await expect(page.locator('#draft-status')).toContainText('saved locally');
 page.once('dialog',d=>d.accept());await page.reload();await page.locator('#local-drafts summary').click();await page.locator(`[data-draft-key="${key}"]`).getByRole('button',{name:/Restore/}).click();expect(await page.locator('#request').inputValue()).toBe(applied);await edit(page,'output');await expect(page.getByLabel('Output index 0 capacity (CKB)')).toHaveValue('777');await expect(page.getByLabel('Output index 0 data (hex)')).toHaveValue('0x1234');await page.getByRole('button',{name:'Cancel changes'}).click();await other.close();
