test('external removal, replacement and storage failure never claim a missing current draft is saved',async({page,context})=>{
 await ready(page);await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('888');await done(page);const before=await page.locator('#request').inputValue();const key=await page.evaluate(expected=>Object.keys(localStorage).find(k=>k.startsWith('ckb-vm-js:draft:')&&JSON.parse(localStorage.getItem(k)).text===expected),before);const other=await context.newPage();await ready(other);
 await other.evaluate(k=>localStorage.setItem(k,JSON.stringify({version:1,text:'different'})),key);await expect(page.locator('#draft-status')).toContainText('no current local draft');expect(await page.locator('#request').inputValue()).toBe(before);
 await page.getByRole('button',{name:'Save local draft'}).click();expect(JSON.parse(await page.evaluate(k=>localStorage.getItem(k),key)).text).toBe('different');const currentKey=await page.evaluate(expected=>Object.keys(localStorage).find(k=>k.startsWith('ckb-vm-js:draft:')&&JSON.parse(localStorage.getItem(k)).text===expected),before);expect(currentKey).not.toBe(key);await other.evaluate(()=>localStorage.clear());await expect(page.locator('#draft-status')).toContainText('no current local draft');expect(await page.locator('#request').inputValue()).toBe(before);
 await edit(page,'output');await page.getByLabel('Output index 0 capacity (CKB)').fill('887');await done(page);await expect(page.locator('#draft-status')).toContainText('saved locally');expect(JSON.parse(await page.evaluate(k=>localStorage.getItem(k),currentKey)).text).toBe(await page.locator('#request').inputValue());
 await page.evaluate(k=>localStorage.removeItem(k),currentKey);await edit(page,'output');await page.getByRole('button',{name:'Cancel changes'}).click();expect(await page.evaluate(k=>localStorage.getItem(k),currentKey)).toBeNull();await expect(page.locator('#draft-status')).toContainText('no current local draft');await page.locator('#local-drafts summary').click();await page.getByRole('button',{name:'Refresh draft list'}).click();await expect(page.locator('#draft-status')).toContainText('no current local draft');expect(await page.evaluate(k=>localStorage.getItem(k),currentKey)).toBeNull();await page.getByRole('button',{name:'Save local draft'}).click();await page.evaluate(()=>{Storage.prototype.getItem=function(){throw new DOMException('Blocked','SecurityError');};});await page.getByRole('button',{name:'Refresh draft list'}).click();await expect(page.locator('#draft-status')).toContainText('storage is unavailable');await expect(page.getByRole('button',{name:'Save local draft'})).toBeVisible();await other.close();
});

