test('existing script choices use the same script identifier as the card',async({page})=>{
 await ready(page);await page.locator('.example-menu summary').click();await page.locator('#sample').selectOption('script-failure');await page.getByRole('button',{name:'Load sample'}).click();await edit(page,'output');const identity=await page.locator('dialog .script-identity').first().textContent();const marker=identity.match(/Script \d+/)?.[0];expect(marker).toBeTruthy();await page.getByText('Output index 0 lock code reference',{exact:true}).click();const selector=page.getByLabel('Output index 0 lock · use existing script');const request=JSON.parse(await page.locator('#request').inputValue());const script=request.transaction.outputs[0].lock;const options=await selector.locator('option').allTextContents();expect(options.some(s=>s.startsWith(`${marker} ·`)&&s.includes(script.code_hash.slice(0,16))&&s.endsWith(`args ${script.args}`))).toBe(true);await done(page);
});


test('unapplied header and reference drafts warn before reload',async({page})=>{
 await ready(page);await page.getByRole('button',{name:'Manage header deps'}).click();await page.getByRole('button',{name:'Create header'}).click();const number=page.getByLabel('Header Block number (RPC hex)');await number.fill('0x65');let pending=page.waitForEvent('dialog');let reload=page.reload();let warning=await pending;expect(warning.type()).toBe('beforeunload');await warning.accept();await reload;await expect(page.locator('#status')).toHaveText('Ready');
 await edit(page,'input');await page.getByText('Advanced · since & reference').click();await page.getByText('Reference & origin',{exact:true}).click();const hash=page.getByLabel('Input index 0 transaction hash');await hash.fill(`0x${'ab'.repeat(32)}`);pending=page.waitForEvent('dialog');reload=page.reload();warning=await pending;expect(warning.type()).toBe('beforeunload');await warning.accept();await reload;await expect(page.locator('#status')).toHaveText('Ready');
});

for(const viewport of [{width:1100,height:650},{width:390,height:252}])test(`hash type keyboard selection keeps focus and scroll at ${viewport.width}x${viewport.height}`,async({page})=>{
 await page.setViewportSize(viewport);await ready(page);const request=page.locator('#request');const before=await request.inputValue();await edit(page,'input');await page.getByText('Input index 0 lock code reference',{exact:true}).click();const group=page.getByRole('radiogroup',{name:'Input index 0 lock hash_type'});await group.getByRole('radio',{name:'data2',exact:true}).click();const from=group.getByRole('radio',{name:'data2',exact:true});await expect(from).toBeFocused();const scroll=await page.locator('dialog').evaluate(e=>e.scrollTop);await from.press('ArrowRight');const chosen=group.getByRole('radio',{name:'type',exact:true});await expect(chosen).toBeFocused();await expect(chosen).toHaveAttribute('aria-checked','true');await expect(from).toHaveAttribute('aria-checked','false');expect(Math.abs(await page.locator('dialog').evaluate(e=>e.scrollTop)-scroll)).toBeLessThanOrEqual(2);expect(JSON.parse(await request.inputValue()).context.cells[0].output.lock.hash_type).toBe('type');await page.keyboard.press('Escape');expect(await request.inputValue()).toBe(before);
});

test('witness order changes only witnesses, supports keyboard, boundaries, save and cancel',async({page})=>{
 await page.setViewportSize({width:390,height:583});await ready(page);await page.locator('#advanced summary').click();const request=page.locator('#request');const original=JSON.parse(await request.inputValue());original.transaction.witnesses=['0xaa','0xbb','0xcc'];original.extra={kept:'unchanged'};await request.fill(JSON.stringify(original));const baseline=await request.inputValue();await page.locator('#advanced summary').click();await page.getByRole('button',{name:'Manage witnesses'}).click();await expect(page.locator('dialog')).toContainText('does not move inputs');await expect(page.getByRole('button',{name:'Move witness index 0 up'})).toBeDisabled();await expect(page.getByRole('button',{name:'Move witness index 2 down'})).toBeDisabled();const up=page.getByRole('button',{name:'Move witness index 2 up'});await up.focus();await page.keyboard.press('Enter');let changed=JSON.parse(await request.inputValue());expect(changed.transaction.witnesses).toEqual(['0xaa','0xcc','0xbb']);expect(changed.transaction.inputs).toEqual(original.transaction.inputs);expect(changed.transaction.cell_deps).toEqual(original.transaction.cell_deps);expect(changed.context).toEqual(original.context);await expect(page.locator('dialog .witness-order-notice')).toContainText('Inputs stayed in place');await expect(page.getByRole('button',{name:'Move witness index 1 up'})).toBeFocused();await page.getByRole('button',{name:'Cancel changes'}).click();expect(await request.inputValue()).toBe(baseline);
 await page.getByRole('button',{name:'Manage witnesses'}).click();await page.getByRole('button',{name:'Move witness index 0 down'}).click();await done(page);changed=JSON.parse(await request.inputValue());expect(changed.transaction.witnesses).toEqual(['0xbb','0xaa','0xcc']);expect(changed.transaction.inputs).toEqual(original.transaction.inputs);await page.getByRole('button',{name:'Witness index 0 · open details'}).click();await expect(page.locator('dialog .witness-sort')).toBeHidden();await done(page);
});

test('cell dependency order changes only dependencies and respects list save or cancel',async({page})=>{
 await page.setViewportSize({width:390,height:583});await ready(page);await page.locator('#advanced summary').click();const request=page.locator('#request');const original=JSON.parse(await request.inputValue());original.transaction.cell_deps.push({out_point:structuredClone(original.transaction.inputs[0].previous_output),dep_type:'dep_group',unknown:'preserved'});original.transaction.cell_deps.push(null);original.transaction.witnesses=['0xaa'];await request.fill(JSON.stringify(original));const baseline=await request.inputValue();await page.locator('#advanced summary').click();await page.getByRole('button',{name:'Manage cell deps'}).click();await expect(page.locator('dialog')).toContainText('other lists and resolved cells stay unchanged');await expect(page.getByRole('button',{name:'Move cell dependency index 0 up'})).toBeDisabled();await expect(page.getByRole('button',{name:'Move cell dependency index 2 down'})).toBeDisabled();await page.getByRole('button',{name:'Move cell dependency index 1 up'}).focus();await page.keyboard.press('Enter');let changed=JSON.parse(await request.inputValue());expect(changed.transaction.cell_deps).toEqual([original.transaction.cell_deps[1],original.transaction.cell_deps[0],null]);expect(changed.transaction.inputs).toEqual(original.transaction.inputs);expect(changed.transaction.witnesses).toEqual(original.transaction.witnesses);expect(changed.context).toEqual(original.context);await expect(page.getByRole('button',{name:/^Edit cell dep index 0 ·/})).toBeFocused();await page.getByRole('button',{name:'Cancel changes'}).click();expect(await request.inputValue()).toBe(baseline);
 await page.getByRole('button',{name:'Manage cell deps'}).click();await page.getByRole('button',{name:'Move cell dependency index 0 down'}).click();await done(page);changed=JSON.parse(await request.inputValue());expect(changed.transaction.cell_deps).toEqual([original.transaction.cell_deps[1],original.transaction.cell_deps[0],null]);expect(changed.context).toEqual(original.context);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
});

